def unescaped_at(pattern, idx):
    n = 0; j = idx - 1
    while j >= 0 and pattern[j] == '\\':
        n += 1; j -= 1
    return n % 2 == 0


def find_unsupported(pattern):
    # Rust's regex engine deliberately rejects look-around and backrefs.  Python
    # supports some of them, so reject the visible cases to mimic sd.
    for token in ["(?<=", "(?<!", "(?=", "(?!"]:
        k = pattern.find(token)
        if k >= 0:
            return k, len(token), "look-around, including look-ahead and look-behind, is not supported"
    i = 0
    in_class = False
    while i < len(pattern)-1:
        c = pattern[i]
        if c == '[' and unescaped_at(pattern, i):
            in_class = True
        elif c == ']' and unescaped_at(pattern, i):
            in_class = False
        if not in_class and c == '\\' and pattern[i+1].isdigit() and pattern[i+1] != '0' and unescaped_at(pattern, i):
            return i, 2, "backreferences are not supported"
        i += 1
    return None


def format_regex_parse_error(pattern, pos, span_len, msg):
    sys.stderr.write("error: invalid regex regex parse error:\n")
    sys.stderr.write(f"    {pattern}\n")
    sys.stderr.write("    " + " "*pos + "^"*max(1, span_len) + "\n")
    sys.stderr.write("error: " + msg + "\n")
    raise UsageExit(1)


def consume_inline_flags(pattern, flags):
    # sd starts regexes in multi-line mode. Leading inline flag switches adjust
    # the remainder of the expression. This handles the common global forms:
    # (?i), (?-i), (?s), (?-s), (?m), (?-m), (?x), (?-x), (?U).
    pos = 0
    ungreedy = False
    while pattern.startswith('(?', pos):
        end = pattern.find(')', pos+2)
        if end < 0:
            break
        body = pattern[pos+2:end]
        if ':' in body or '<' in body or '=' in body or '!' in body or body == 'P':
            break
        if not body or any(ch not in 'imsxU-' for ch in body):
            break
        neg = False
        for ch in body:
            if ch == '-':
                neg = True; continue
            bit = {'i': re.IGNORECASE, 'm': re.MULTILINE, 's': re.DOTALL, 'x': re.VERBOSE}.get(ch)
            if ch == 'U':
                ungreedy = True; continue
            if bit:
                if neg:
                    flags &= ~bit
                else:
                    flags |= bit
        pos = end + 1
    return pattern[pos:], flags, ungreedy


def translate_hex_braces(p):
    def repl(m):
        try:
            return chr(int(m.group(1), 16))
        except Exception:
            return m.group(0)
    return re.sub(r"\\x\{([0-9A-Fa-f]+)\}", repl, p)


def translate_named_groups(p):
    # Rust accepts (?<name>...), Python wants (?P<name>...). Do not touch lookbehind.
    return re.sub(r"\(\?<([A-Za-z_][A-Za-z0-9_]*)>", r"(?P<\1>", p)


def translate_posix_classes(p):
    # Best-effort translations for common POSIX bracket classes used by Rust regex.
    repls = {
        '[[:alpha:]]': r'[^\W\d_]',
        '[[:alnum:]]': r'[^\W_]',
        '[[:digit:]]': r'\d',
        '[[:space:]]': r'\s',
        '[[:word:]]': r'\w',
        '[[:lower:]]': r'[a-z]',
        '[[:upper:]]': r'[A-Z]',
    }
    for a,b in repls.items():
        p = p.replace(a,b)
    return p


def translate_unicode_props(p):
    # A small subset, enough for typical examples. Python stdlib lacks \p{..}.
    p = re.sub(r"\\p\{Greek\}", r"[\u0370-\u03FF\u1F00-\u1FFF]", p)
    p = re.sub(r"\\P\{Greek\}", r"[^\u0370-\u03FF\u1F00-\u1FFF]", p)
    p = re.sub(r"\\p\{L\}", r"[^\W\d_]", p)
    p = re.sub(r"\\p\{Letter\}", r"[^\W\d_]", p)
    p = re.sub(r"\\P\{L\}", r"[\W\d_]", p)
    return p


def translate_dots(p, dotall):
    # Keep invalid UTF-8 bytes (represented by surrogateescape) outside matches
    # for '.', close to regex::bytes in Unicode mode.
    out = []
    in_class = False
    esc = False
    dot_repl = r"[^\udc80-\udcff]" if dotall else r"[^\n\udc80-\udcff]"
    for ch in p:
        if esc:
            out.append(ch); esc = False; continue
        if ch == '\\':
            out.append(ch); esc = True; continue
        if ch == '[':
            in_class = True; out.append(ch); continue
        if ch == ']' and in_class:
            in_class = False; out.append(ch); continue
        if ch == '.' and not in_class:
            out.append(dot_repl); continue
        out.append(ch)
    return ''.join(out)


def make_pattern(find, opts):
    if opts.fixed:
        pat = re.escape(find)
        flags = re.MULTILINE
        return re.compile(pat, flags)
    flags = re.MULTILINE
    # Flag string behavior follows observed sd defaults: m is already on; e
    # disables it. c/i are order-sensitive; s turns DOTALL on.
    if opts.flags:
        for ch in opts.flags:
            if ch == 'i':
                flags |= re.IGNORECASE
            elif ch == 'c':
                flags &= ~re.IGNORECASE
            elif ch == 's':
                flags |= re.DOTALL
        if 'e' in opts.flags:
            flags &= ~re.MULTILINE
    pat = find
    unsupported = find_unsupported(pat)
    if unsupported:
        format_regex_parse_error(pat, *unsupported)
    pat, flags, ungreedy = consume_inline_flags(pat, flags)
    if opts.flags and 'w' in opts.flags:
        pat = r"\b(?:" + pat + r")\b"
    pat = translate_named_groups(pat)
    pat = translate_hex_braces(pat)
    pat = pat.replace(r"\z", r"\Z")
    pat = translate_posix_classes(pat)
    pat = translate_unicode_props(pat)
    # Python doesn't have a global ungreedy flag. A minimal approximation flips
    # simple greedy quantifiers when (?U) is used.
    if ungreedy:
        pat = re.sub(r"(?<!\\)([+*?])(?!\?)", r"\1?", pat)
        pat = re.sub(r"(?<!\\)(\{\d+(?:,\d*)?\})(?!\?)", r"\1?", pat)
    pat = translate_dots(pat, bool(flags & re.DOTALL))
    try:
        return re.compile(pat, flags)
    except re.error as e:
        msg = getattr(e, 'msg', str(e))
        pos = getattr(e, 'pos', 0) or 0
        # Tweak the most common error wording.
        if 'unterminated character set' in msg:
            msg = 'unclosed character class'
        format_regex_parse_error(find, min(pos, len(find)), 1, msg)


def get_group(m, key):
    try:
        if isinstance(key, int):
            if key > m.re.groups:
                return ''
            val = m.group(key)
        else:
            if key not in m.re.groupindex:
                return ''
            val = m.group(key)
        return '' if val is None else val
    except Exception:
        return ''


def replacement_func(repl_text, fixed=False):
    if fixed:
        return lambda m: repl_text

    # Pre-validate numeric ambiguity, matching regex crate's helpful error.
    i = 0
    while i < len(repl_text):
        if repl_text[i] == '$' and i+1 < len(repl_text) and repl_text[i+1] != '$':
            j = i+1
            if repl_text[j].isdigit():
                while j < len(repl_text) and repl_text[j].isdigit():
                    j += 1
                if j < len(repl_text) and (repl_text[j].isalpha() or repl_text[j] == '_'):
                    ref = repl_text[i:j]
                    caret_len = len(ref)
                    msg = (f"The numbered capture group `{ref}` in the replacement text is ambiguous.\n"
                           f"hint: Use curly braces to disambiguate it `${{{ref[1:]}}}{repl_text[j]}`.\n"
                           f"{repl_text}\n" + " "*i + "^"*caret_len)
                    raise ReplacementError(msg)
                i = j; continue
        i += 1

    def expand(m):
        out = []
        i = 0
        s = repl_text
        while i < len(s):
            ch = s[i]
            if ch != '$':
                out.append(ch); i += 1; continue
            if i + 1 >= len(s):
                out.append('$'); i += 1; continue
            nxt = s[i+1]
            if nxt == '$':
                out.append('$'); i += 2; continue
            if nxt == '{':
                end = s.find('}', i+2)
                if end == -1:
                    out.append(s[i:]); break
                name = s[i+2:end]
                if name.isdigit():
                    out.append(get_group(m, int(name or '0')))
                else:
                    out.append(get_group(m, name))
                i = end + 1; continue
            if nxt.isdigit():
                j = i+1
                while j < len(s) and s[j].isdigit():
                    j += 1
                out.append(get_group(m, int(s[i+1:j] or '0')))
                i = j; continue
            if nxt.isalpha() or nxt == '_':
                j = i+1
                while j < len(s) and (s[j].isalnum() or s[j] == '_'):
                    j += 1
                out.append(get_group(m, s[i+1:j]))
                i = j; continue
            out.append('$')
            i += 1
        return ''.join(out)
    return expand


def process_text(data_bytes, regex, repl_fn, max_repl):
    text = data_bytes.decode('utf-8', 'surrogateescape')
    count = 0 if max_repl == 0 else max_repl
    try:
        out = regex.sub(repl_fn, text, count=count)
    except ReplacementError:
        raise
    return out.encode('utf-8', 'surrogateescape')


def run(opts, find, replace, files):
    regex = make_pattern(find, opts)
    try:
        repl_fn = replacement_func(replace, opts.fixed)
    except ReplacementError as e:
        sys.stderr.write("error: " + str(e) + "\n")
        return 1

    def transform(data):
        return process_text(data, regex, repl_fn, opts.max_repl)

    if files:
        multiple = len(files) > 1
        for path in files:
            if not os.path.exists(path):
                sys.stderr.write(f"error: invalid path: {path}\n")
                return 1
            if os.path.isdir(path):
                sys.stderr.write("error: No such device (os error 19)\n")
                return 1
            try:
                with open(path, 'rb') as f:
                    data = f.read()
                out = transform(data)
                if opts.preview:
                    if multiple:
                        sys.stdout.buffer.write(f"----- FILE {path} -----\n".encode())
                    sys.stdout.buffer.write(out)
                else:
                    with open(path, 'wb') as f:
                        f.write(out)
            except OSError as e:
                sys.stderr.write(f"error: {e}\n")
                return 1
            except ReplacementError as e:
                sys.stderr.write("error: " + str(e) + "\n")
                return 1
        return 0
    else:
        try:
            data = sys.stdin.buffer.read()
            sys.stdout.buffer.write(transform(data))
            return 0
        except ReplacementError as e:
            sys.stderr.write("error: " + str(e) + "\n")
            return 1


def main():
    try:
        opts, find, replace, files = parse_args(sys.argv[1:])
        code = run(opts, find, replace, files)
        raise SystemExit(code)
    except UsageExit as e:
        raise SystemExit(e.code)

if __name__ == '__main__':
    main()
